class TestConfig:
    @pytest.fixture
    def app(self):
        app = Flask(__name__)
        app.config["MY_SECRET"] = "a-secret-value"
        app.config["API_KEY"] = "some-key"
        app.config["DATABASE_URL"] = "postgres://localhost/db"
        return app

    @pytest.fixture
    def invoke(self, app, runner):
        cli = FlaskGroup(create_app=lambda: app)
        return partial(runner.invoke, cli)

    def test_config(self, invoke):
        result = invoke(["config"])
        assert result.exit_code == 0
        data = json.loads(result.output)
        assert data["MY_SECRET"] == "***"
        assert data["API_KEY"] == "***"
        assert data["SECRET_KEY"] == "***"
        assert data["DATABASE_URL"] == "postgres://localhost/db"

    def test_config_in_help(self, invoke):
        result = invoke(["--help"])
        assert result.exit_code == 0
        assert "config" in result.output


